using System.Text.Json;
using MySqlConnector;
namespace WoWItemEditor;
internal sealed record CreatedQuest(string OperationId,int NpcId,ulong SpawnId,int QuestId,string Title,string NpcName,string State,string SnapshotJson);
internal static class CreatedQuests
{
    internal static async Task Initialize(MySqlConnection db){await ContentEditing.InitializeAsync(db);await QuestCreation.Initialize(db);using var cmd=new MySqlCommand($"ALTER TABLE {QuestCreation.History} ADD COLUMN IF NOT EXISTS DeletedUtc DATETIME(6) NULL, ADD COLUMN IF NOT EXISTS RepairNote TEXT NULL",db);await cmd.ExecuteNonQueryAsync();}
    internal static async Task<List<CreatedQuest>> List(){using var db=await DatabaseConnection.OpenAsync(CatalogRepository.Database);await Initialize(db);return(await WorldDrops.Query(db,null,$"SELECT h.*,c.name FROM {QuestCreation.History} h LEFT JOIN {QuestCreation.World}.creature_template c ON c.entry=h.NpcId ORDER BY CreatedUtc DESC")).Select(r=>new CreatedQuest(r["OperationId"]!,int.Parse(r["NpcId"]!),ulong.Parse(r["SpawnId"]!),int.Parse(r["QuestId"]!),r["Title"]!,r["name"]??"Removed NPC",r["DeletedUtc"] is null?"Active":"Deleted",r["SnapshotJson"]!)).ToList();}
    private static IEnumerable<(string Table,string Key,string Value)> Scope(CreatedQuest entry){foreach(string t in new[]{"creature_queststarter","creature_questender"})yield return(t,"quest",entry.QuestId.ToString());foreach(string t in new[]{"quest_details","quest_offer_reward","quest_request_items","quest_template_addon","quest_template"})yield return(t,"ID",entry.QuestId.ToString());yield return("quest_objectives","QuestID",entry.QuestId.ToString());yield return("areatrigger_involvedrelation","quest",entry.QuestId.ToString());yield return("creature","guid",entry.SpawnId.ToString());foreach(string t in new[]{"creature_equip_template","creature_template_model"})yield return(t,"CreatureID",entry.NpcId.ToString());yield return("creature_template","entry",entry.NpcId.ToString());}
    internal static async Task<string> Capture(CreatedQuest entry,MySqlConnection db,MySqlTransaction? tx=null,bool locked=false){var rows=new Dictionary<string,List<Dictionary<string,string?>>>();foreach(var (table,key,value) in Scope(entry))rows[table]=await WorldDrops.Query(db,tx,$"SELECT * FROM {QuestCreation.World}.{table} WHERE {key}={value}"+(locked?" FOR UPDATE":""));return HistoryActions.Canonical(new(rows));}
    internal static async Task<string> Review(CreatedQuest entry){using var db=await DatabaseConnection.OpenAsync(CatalogRepository.Database);return await Capture(entry,db);}
    internal static async Task DeleteCore(CreatedQuest entry,string expected,MySqlConnection db,MySqlTransaction tx)
    {
        var audit=(await WorldDrops.Query(db,tx,$"SELECT * FROM {QuestCreation.History} WHERE NpcId={entry.NpcId} AND QuestId={entry.QuestId} AND SpawnId={entry.SpawnId} FOR UPDATE")).SingleOrDefault()??throw new InvalidOperationException("Creation audit not found.");
        if(audit["OperationId"]!=entry.OperationId||audit["DeletedUtc"] is not null||audit["SnapshotJson"]!=entry.SnapshotJson)throw new InvalidOperationException("The creation record changed. Refresh the list.");
        using var snapshot=JsonDocument.Parse(entry.SnapshotJson);if(snapshot.RootElement.GetProperty("source").GetProperty("Npc").GetProperty("Id").GetInt32()==entry.NpcId)throw new InvalidOperationException("Cannot delete the original NPC.");
        if(await Capture(entry,db,tx,true)!=expected)throw new InvalidOperationException("The NPC or quest changed after review. Refresh and review again.");
        string world=QuestCreation.World;var checks=new[]{ $"SELECT guid FROM {world}.creature WHERE id={entry.NpcId} AND guid<>{entry.SpawnId}",$"SELECT id FROM {world}.creature_queststarter WHERE (id={entry.NpcId} AND quest<>{entry.QuestId})",$"SELECT id FROM {world}.creature_questender WHERE (id={entry.NpcId} AND quest<>{entry.QuestId})",$"SELECT id FROM {world}.gameobject_queststarter WHERE quest={entry.QuestId}",$"SELECT id FROM {world}.gameobject_questender WHERE quest={entry.QuestId}",$"SELECT ID FROM {world}.quest_objectives WHERE QuestID<>{entry.QuestId} AND Type IN(0,3) AND ObjectID={entry.NpcId}",$"SELECT ID FROM {world}.quest_template_addon WHERE PrevQuestID IN({entry.QuestId},-{entry.QuestId}) OR NextQuestID={entry.QuestId} OR BreadcrumbForQuestId={entry.QuestId}"};foreach(var sql in checks)if((await WorldDrops.Query(db,tx,sql+" FOR UPDATE")).Count>0)throw new InvalidOperationException("Other content references this creation. Remove those links before deleting it.");
        foreach(var (table,key,value) in Scope(entry)){using var cmd=new MySqlCommand($"DELETE FROM {world}.{table} WHERE {key}={value}",db,tx);await cmd.ExecuteNonQueryAsync();}
        using var mark=new MySqlCommand($"UPDATE {QuestCreation.History} SET DeletedUtc=UTC_TIMESTAMP(6) WHERE OperationId=@op",db,tx);mark.Parameters.AddWithValue("@op",entry.OperationId);await mark.ExecuteNonQueryAsync();
    }
    internal static Task<bool> Delete(CreatedQuest entry,string expected)=>ContentEditing.Transaction(async(db,tx)=>{await DeleteCore(entry,expected,db,tx);return true;});
    internal static async Task<int> RepairAvailability(){using var db=await DatabaseConnection.OpenAsync(CatalogRepository.Database);await Initialize(db);return await ContentEditing.Transaction(async(connection,tx)=>{using var cmd=new MySqlCommand($"UPDATE {QuestCreation.World}.quest_template q JOIN {QuestCreation.History} h ON h.QuestId=q.ID SET q.AllowableRaces=18446744073709551615,h.RepairNote='Corrected empty allowed-races mask to all races' WHERE q.AllowableRaces=0 AND h.DeletedUtc IS NULL",connection,tx);return await cmd.ExecuteNonQueryAsync();});}
}
